<?php
namespace VPM\Booking;
if(!defined('ABSPATH'))exit;
final class Conditions {
    public static function get(int $partner):array {global $wpdb;return json_decode((string)$wpdb->get_var($wpdb->prepare('SELECT payload FROM '.DB::table('conditions').' WHERE partner_id=%d',$partner)),true)?:array();}
    public static function fee(array $r):array {$kind=$r['kind']??'percent';Config::require(in_array($kind,array('percent','fixed'),true),'invalid_fee_kind');return array('kind'=>$kind,'value'=>Commerce::number($r['value']??0,0,$kind==='percent'?10000:100000000));}
    public static function save(int $partner,array $d):void {
        Tenants::authorize($partner,true);if(!empty($d['ui_units'])){foreach($d['tiers']??array()as $i=>$r){if(!empty($r['enabled']))$d['tiers'][$i]['value']=Promotions::decimal((string)($r['value']??''),($r['kind']??'percent')==='percent'?10000:100000000);}if(isset($d['no_show']['value']))$d['no_show']['value']=Promotions::decimal((string)$d['no_show']['value'],($d['no_show']['kind']??'percent')==='percent'?10000:100000000);}$out=array();foreach(array('buffer_before_minutes'=>1440,'buffer_after_minutes'=>1440,'minimum_notice_minutes'=>525600,'delay_grace_minutes'=>1440)as $k=>$max)$out[$k]=Commerce::number($d[$k]??0,0,$max);
        $out['minimum_days']=Commerce::number($d['minimum_days']??1,1,181);$out['maximum_days']=Commerce::number($d['maximum_days']??181,$out['minimum_days'],181);$out['delay_hourly_cents']=Commerce::number($d['delay_hourly_cents']??0,0,10000000);$out['cancellation_enabled']=!empty($d['cancellation_enabled']);$out['tiers']=array();$seen=array();
        Config::require(is_array($d['tiers']??array())&&count($d['tiers']??array())<=12,'invalid_cancellation_tiers');foreach($d['tiers']??array()as $r){if(empty($r['enabled']))continue;$hours=Commerce::number($r['hours']??0,0,8760);Config::require(!isset($seen[$hours]),'duplicate_cancellation_threshold');$seen[$hours]=true;$out['tiers'][]=array('hours'=>$hours)+self::fee($r);}
        usort($out['tiers'],function($a,$b){return $b['hours']<=>$a['hours'];});Config::require(!$out['cancellation_enabled']||($out['tiers']&&end($out['tiers'])['hours']===0),'cancellation_zero_tier_required');$out['no_show_enabled']=!empty($d['no_show_enabled']);$out['no_show']=self::fee($d['no_show']??array());
        global $wpdb;DB::query($wpdb->prepare('INSERT INTO '.DB::table('conditions').' (partner_id,payload) VALUES (%d,%s) ON DUPLICATE KEY UPDATE payload=VALUES(payload)',$partner,wp_json_encode($out)));Operations::audit('partner.conditions_saved','partner',$partner);
    }
    public static function eligible(array $c,array $policy,?int $now=null):bool {$days=(int)ceil(($c['return_utc']-$c['departure_utc'])/DAY_IN_SECONDS);return $c['departure_utc']>=($now??time())+($policy['minimum_notice_minutes']??0)*60&&$days>=($policy['minimum_days']??1)&&$days<=($policy['maximum_days']??181);}
    public static function occupancy(array $c,array $policy):array {if(!empty($c['_occupancy_applied']))return $c;$c['departure_utc']-=($policy['buffer_before_minutes']??0)*60;$c['return_utc']+=($policy['buffer_after_minutes']??0)*60;$c['_occupancy_applied']=true;return $c;}
    public static function assessment(array $b,string $kind='cancellation',?int $at=null):array {
        $q=Core::snapshot($b);$policy=$q['booking_rules']??array();$at=$at??time();$handover=$q['partner_service']['confirmed_handover_utc']??$q['travel']['departure_utc']??null;$rule=array('kind'=>'percent','value'=>0);$hours=$handover===null?null:($handover-$at)/HOUR_IN_SECONDS;
        if($kind==='no_show'){global $wpdb;$delayed=(int)$wpdb->get_var($wpdb->prepare('SELECT MAX(collection_utc) FROM '.DB::table('delays')." WHERE booking_id=%d AND leg='arrival'",$b['id']));if($handover!==null)$handover=max($handover,$delayed);Config::require(!empty($policy['no_show_enabled'])&&$handover!==null&&$at>=$handover,'no_show_not_available');$rule=$policy['no_show'];}
        elseif(!empty($policy['cancellation_enabled'])&&$hours!==null){foreach($policy['tiers']as $r)if($hours>=$r['hours']||$r['hours']===0){$rule=$r;break;}}
        $basis=in_array($b['payment_state'],array('paid','partially_refunded','refunded'),true)?$q['charged']:0;$fee=$rule['kind']==='fixed'?$rule['value']:intdiv($basis*$rule['value']+5000,10000);$fee=min($basis,$fee);return array('kind'=>$kind,'requested_at'=>$at,'basis_cents'=>$basis,'fee_cents'=>$fee,'refund_total_cents'=>$basis-$fee,'currency'=>'eur','rule'=>$rule);
    }
    public static function decision(array $b):array {
        $q=Core::snapshot($b);if(isset($q['cancellation_decision']))return $q['cancellation_decision'];global $wpdb;$at=$wpdb->get_var($wpdb->prepare('SELECT created_at FROM '.DB::table('changes')." WHERE booking_id=%d AND kind='cancellation'",$b['id']));return self::assessment($b,'cancellation',$at?(int)$at:time());
    }
    public static function freeze(array $b,string $kind='cancellation'):array {
        $q=Core::snapshot($b);if(isset($q['cancellation_decision'])){Config::require($q['cancellation_decision']['kind']===$kind,'cancellation_kind_already_fixed');return $b;}$q['cancellation_decision']=$kind==='cancellation'?self::decision($b):self::assessment($b,$kind);DB::update('bookings',array('snapshot'=>wp_json_encode($q)),array('id'=>$b['id']));$b['snapshot']=wp_json_encode($q);return $b;
    }
    public static function no_show(string $reference):array {
        $b=Core::booking($reference);Tenants::authorize((int)$b['partner_id'],true);$b=DB::tx(function()use($reference){$b=Core::booking($reference,true);Config::require($b['state']==='confirmed'&&in_array($b['payment_state'],array('paid','partially_refunded'),true),'no_show_not_available');$b=self::freeze($b,'no_show');Operations::audit('booking.no_show_declared','booking',(int)$b['id']);Logistics::partner_event($b,'partner.no_show_declared',array('assessment'=>self::decision($b)));return $b;});return Flow::cancel_request($b['public_id']);
    }
    public static function delay(string $reference,int $collection,string $key,string $leg='return'):array {
        Config::key($key);$b=Core::booking($reference);Tenants::authorize((int)$b['partner_id'],true);$q=Core::snapshot($b);Config::require(in_array($leg,array('arrival','return'),true),'invalid_delay_leg');$original=$q['travel'][$leg==='arrival'?'departure_utc':'return_utc']??0;Config::require($b['state']==='confirmed'&&$original>0&&$collection>=$original&&$collection<=$original+30*DAY_IN_SECONDS,'invalid_delay');
        global $wpdb;$source=$q['fulfilment']??array();return DB::tx(function()use($wpdb,$reference,$collection,$key,$source,$leg){if(($source['mode']??'')==='manual')$rate=DB::row('rates','id',(int)$source['rate_id'],true);$b=Core::booking($reference,true);$q=Core::snapshot($b);$old=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.DB::table('delays').' WHERE booking_id=%d AND request_key=%s',$b['id'],$key),ARRAY_A);if($old){Config::require((int)$old['collection_utc']===$collection&&$old['leg']===$leg,'idempotency_conflict');return json_decode($old['payload'],true);}
            Config::require($b['state']==='confirmed','invalid_delay');$last=(int)$wpdb->get_var($wpdb->prepare('SELECT MAX(collection_utc) FROM '.DB::table('delays').' WHERE booking_id=%d AND leg=%s',$b['id'],$leg));$original=$q['travel'][$leg==='arrival'?'departure_utc':'return_utc'];Config::require($collection>=max($last,$original),'delay_cannot_shorten');$policy=$q['booking_rules']??array();$minutes=max(0,(int)ceil(($collection-$original)/60)-($policy['delay_grace_minutes']??0));$result=array('leg'=>$leg,'collection_utc'=>$collection,'estimated_additional_cents'=>(int)ceil($minutes/60)*($policy['delay_hourly_cents']??0),'currency'=>'eur','capacity'=>'requires_partner_confirmation','billing'=>'partner_review_no_automatic_charge');
            if(($source['mode']??'')==='manual'&&$leg==='return'){$allocation=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.DB::table('allocations').' WHERE booking_id=%d FOR UPDATE',$b['id']),ARRAY_A);Config::require($allocation&&$allocation['state']==='confirmed','allocation_not_confirmed');$end=$collection+($policy['buffer_after_minutes']??0)*60;if($end>(int)$allocation['ends_at']){$c=array('departure_utc'=>(int)$allocation['ends_at'],'return_utc'=>$end,'charging_required'=>(bool)$allocation['charging'],'_occupancy_applied'=>true);$rate['enabled']=1;if(Adapters::available($rate,$c,true)){DB::update('allocations',array('ends_at'=>$end),array('booking_id'=>$b['id']));$result['capacity']='extended';}else{$result['capacity']='conflict';}}else{$result['capacity']='extended';}}
            if($leg==='arrival')$result['capacity']='unchanged';$service=$q['offer_selection']['service']??$source['service']??'parking';$hours=Commerce::get((int)$b['partner_id'])['services'][$service]['hours']??array();$result['service_time']=Commerce::open($hours,$collection,$q['travel']['timezone'])?'within_hours':'partner_review';$review=in_array($result['capacity'],array('conflict','requires_partner_confirmation'),true)||$result['service_time']==='partner_review';
            $id=DB::insert('delays',array('leg'=>$leg,'needs_review'=>$review?1:0,'booking_id'=>$b['id'],'request_key'=>$key,'collection_utc'=>$collection,'payload'=>wp_json_encode($result),'created_at'=>time()));Logistics::partner_event($b,'partner.delay_recorded',$result,'delay:'.$id);Automation::booking_event($b,'booking.delay_recorded',$result,'delay:'.$id);Operations::audit('booking.delay_recorded','booking',(int)$b['id']);return $result;
        });
    }
    public static function blocked(int $partner):bool {global $wpdb;return (int)$wpdb->get_var($wpdb->prepare('SELECT COUNT(*) FROM '.DB::table('delays')." d INNER JOIN ".DB::table('bookings')." b ON b.id=d.booking_id WHERE b.partner_id=%d AND b.state<>'cancelled' AND d.needs_review=1",$partner))>0;}
    public static function resolve(int $id):void {global $wpdb;DB::tx(function()use($wpdb,$id){$d=DB::row('delays','id',$id,true);Config::require((bool)$d,'delay_not_found');$b=DB::row('bookings','id',$d['booking_id'],true);Tenants::authorize((int)$b['partner_id'],true);$q=Core::snapshot($b);$p=json_decode($d['payload'],true);if(($p['capacity']??'')==='conflict'&&$b['state']!=='cancelled'){$end=(int)$wpdb->get_var($wpdb->prepare('SELECT ends_at FROM '.DB::table('allocations').' WHERE booking_id=%d',$b['id']));Config::require($end>=(int)$d['collection_utc']+($q['booking_rules']['buffer_after_minutes']??0)*60,'delay_capacity_unresolved');}DB::update('delays',array('needs_review'=>0),array('id'=>$id));Operations::audit('booking.delay_reviewed','booking',(int)$b['id']);});}

}
